package com.lyrashop.order.controller;
import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.lyrashop.order.dto.*;import com.lyrashop.order.service.VoucherService;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/v1/admin/vouchers") @PreAuthorize("hasAnyRole('ADMIN','ORDER_MANAGER')")
public class AdminVoucherController{private final VoucherService service;public AdminVoucherController(VoucherService service){this.service=service;}@GetMapping public List<AdminVoucherResponse> list(){return service.adminList();}@GetMapping("/page")public com.lyrashop.common.dto.PageResponse<AdminVoucherResponse> page(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String query,@RequestParam(required=false)Boolean active,@RequestParam(defaultValue="code")String sort,@RequestParam(defaultValue="asc")String direction){var result=service.adminPage(query,active,com.lyrashop.common.web.AdminPageable.of(page,size,sort,direction,Set.of("code","label","discountValue","startsAt","endsAt","active"),"code"));return com.lyrashop.common.dto.PageResponse.from(result,result.getContent());}@PostMapping public ResponseEntity<AdminVoucherResponse> create(@Valid @RequestBody AdminVoucherRequest r){return ResponseEntity.status(201).body(service.adminCreate(r));}@PutMapping("/{id}") public AdminVoucherResponse update(@PathVariable UUID id,@Valid @RequestBody AdminVoucherRequest r){return service.adminUpdate(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable UUID id){service.adminDeactivate(id);return ResponseEntity.noContent().build();}}
